package com.trimtime.availability;
import com.trimtime.identity.UserAccount; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="barber_days_off") public class DayOff { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="barber_user_id",nullable=false) private UserAccount barber; @Column(name="off_date",nullable=false) private LocalDate date; @Column(name="start_time") private LocalTime startTime; @Column(name="end_time") private LocalTime endTime; @Column(length=255) private String reason; protected DayOff(){} public DayOff(UserAccount barber,LocalDate date,LocalTime startTime,LocalTime endTime,String reason){this.barber=barber;this.date=date;this.startTime=startTime;this.endTime=endTime;this.reason=reason;} public Long getId(){return id;} public LocalDate getDate(){return date;} public LocalTime getStartTime(){return startTime;} public LocalTime getEndTime(){return endTime;} public String getReason(){return reason;} }
